// Security audit script - checks for credential patterns without testing connectivity
const fs = require('fs');
const path = require('path');

function auditCredentials() {
  console.log('🔍 Security Credential Audit\n');

  // Check if .env.test exists
  const envPath = path.join(__dirname, '.env.test');
  if (!fs.existsSync(envPath)) {
    console.log('✅ No .env.test file found');
    return;
  }

  // Read and analyze the file
  const content = fs.readFileSync(envPath, 'utf8');
  const lines = content.split('\n');

  let credentialCount = 0;
  const credentialPatterns = [
    /_KEY=/,
    /_SECRET=/,
    /_TOKEN=/,
    /_PASSWORD=/,
    /_URL=.*@/,
    /AWS_/,
    /API_/,
    /DATABASE_/
  ];

  console.log('📋 Found potential credentials in .env.test:');
  console.log('-' .repeat(50));

  lines.forEach(line => {
    if (line.trim() && !line.startsWith('#')) {
      const isCredential = credentialPatterns.some(pattern => pattern.test(line));

      if (isCredential) {
        credentialCount++;
        // Mask the value for security
        const [key, value] = line.split('=');
        const maskedValue = value ? value.substring(0, 4) + '***' + (value.length > 10 ? value.substring(value.length - 4) : '') : 'undefined';
        console.log(`⚠️  ${key}=${maskedValue}`);
      }
    }
  });

  console.log('-' .repeat(50));
  console.log(`\n📊 Summary: Found ${credentialCount} potential credential entries`);

  if (credentialCount > 0) {
    console.log('\n🔒 Security Recommendations:');
    console.log('1. Rotate all credentials immediately');
    console.log('2. Remove .env.test from version control');
    console.log('3. Use environment-specific .env files (added to .gitignore)');
    console.log('4. Consider using a secrets management service');
  } else {
    console.log('✅ No sensitive credentials detected');
  }
}

// Run the audit
auditCredentials();

