const request = require('supertest');
const app = require('../app_improved');

describe('Security Features Tests', () => {
  test('Should have security headers', async () => {
    const response = await request(app).get('/health');

    expect(response.headers['x-powered-by']).toBeUndefined();
    expect(response.headers['x-content-type-options']).toBe('nosniff');
    expect(response.headers['x-frame-options']).toBe('SAMEORIGIN');
    expect(response.headers['x-xss-protection']).toBe('0');
  });

  test('Should rate limit excessive requests', async () => {
    // Make multiple requests quickly
    const requests = Array(105).fill().map(() => 
      request(app).get('/health')
    );

    const responses = await Promise.all(requests);
    const rateLimited = responses.filter(res => res.status === 429);

    expect(rateLimited.length).toBeGreaterThan(0);
  });

  test('Should validate input parameters', async () => {
    const response = await request(app)
      .get('/users')
      .send({ page: 'invalid', limit: 200 });

    expect(response.status).toBe(400);
    expect(response.body.success).toBe(false);
    expect(response.body.error).toBe('Validation failed');
  });

  test('Should sanitize HTML input', async () => {
    const maliciousInput = '<script>alert("xss")</script>test';
    const response = await request(app)
      .get('/health')
      .send({ check: maliciousInput });

    expect(response.body.check).toBe('test'); // Script tags should be removed
  });

  test('Should handle 404 routes properly', async () => {
    const response = await request(app).get('/nonexistent');

    expect(response.status).toBe(404);
    expect(response.body.success).toBe(false);
  });

  test('Should handle server errors gracefully', async () => {
    // This would test error handling for database failures
    // In a real scenario, you'd mock the database to throw an error
    const response = await request(app).get('/users');

    // Should either succeed or show proper error format
    expect([200, 500]).toContain(response.status);
    if (response.status === 500) {
      expect(response.body.success).toBe(false);
    }
  });
});

