// Enhanced version of app.js with security-focused error handling and input validation
const express = require('express');

const app = express();

// Basic security middleware
app.use(express.json({ limit: '10kb' }));

// Simple input validation middleware
const validateInput = (req, res, next) => {
  // Check for common injection patterns
  const checkForInjection = (value) => {
    if (typeof value !== 'string') return false;

    const injectionPatterns = [
      /<script[^>]*>/i,
      /javascript:/i,
      /on\w+\s*=/i,
      /SELECT.*FROM/i,
      /INSERT.*INTO/i,
      /UPDATE.*SET/i,
      /DELETE.*FROM/i,
      /DROP.*TABLE/i
    ];

    return injectionPatterns.some(pattern => pattern.test(value));
  };

  // Check query parameters
  for (const key in req.query) {
    if (checkForInjection(req.query[key])) {
      return res.status(400).json({
        error: 'Invalid input detected',
        message: 'Potential security threat detected in input'
      });
    }
  }

  // Check body parameters
  if (req.body) {
    for (const key in req.body) {
      if (checkForInjection(req.body[key])) {
        return res.status(400).json({
          error: 'Invalid input detected',
          message: 'Potential security threat detected in input'
        });
      }
    }
  }

  next();
};

// Error handling middleware
