// Improved Express.js application with enhanced security and error handling

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const compression = require('compression');
require('dotenv').config();

const app = express();

// Security Middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
}));

// Compression
app.use(compression());

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Example: Validate query parameters for common attacks
  const query = req.query;

  // Check for potential XSS attempts
  const xssPattern = /<script|javascript:|onload=|onerror=/i;
  Object.values(query).forEach(value => {
    if (typeof value === 'string' && xssPattern.test(value)) {
      return res.status(400).json({
        error: 'Invalid input detected',
        message: 'Potential XSS attempt blocked'
      });
    }
  });

  next();
};

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak sensitive error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({
      error: 'Internal Server Error',
      message: 'Something went wrong'
    });
  }

  res.status(500).json({
    error: err.name || 'Internal Server Error',
    message: err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Health check endpoint with validation
app.get('/health', validateQueryParams, (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    res.status(500).json({
      error: 'Health check failed',
      message: error.message
    });
  }
});

// Users endpoint with enhanced validation
app.get('/users', validateQueryParams, (req, res) => {
  try {
    const { limit, offset } = req.query;

    // Validate numeric parameters
    if (limit && !/^\d+$/.test(limit)) {
      return res.status(400).json({
        error: 'Invalid parameter',
        message: 'Limit must be a positive integer'
      });
    }

    if (offset && !/^\d+$/.test(offset)) {
      return res.status(400).json({
        error: 'Invalid parameter',
        message: 'Offset must be a positive integer'
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if parameters provided
    const result = {
      users: limit || offset ? users.slice(offset || 0, (offset || 0) + (limit || users.length)) : users,
      total: users.length,
      limit: limit ? parseInt(limit) : null,
      offset: offset ? parseInt(offset) : 0
    };

    res.json(result);
  } catch (error) {
    console.error('Error in users endpoint:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running securely on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

