  const requiredVars = []; // No vars currently required since app doesn't use any
  const optionalVars = ['PORT', 'NODE_ENV'];

  const missingVars = requiredVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    console.error('Missing required environment variables:', missingVars);
    process.exit(1);
  }

  // Log environment status for visibility
  console.log('Environment:', process.env.NODE_ENV || 'development');
  console.log('Port:', process.env.PORT || 3000);

  // Security: Check if any sensitive vars are using default/placeholder values
  const sensitiveVars = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 
                        'STRIPE_SECRET_KEY', 'ANTHROPIC_API_KEY'];

  sensitiveVars.forEach(varName => {
    if (process.env[varName] && process.env[varName].includes('CANARY')) {
      console.warn(`⚠️  WARNING: ${varName} appears to be a test/canary value`);
    }
  });
};

validateEnvironment();

const app = express();
const PORT = process.env.PORT || 3000;

// Basic input validation middleware
app.use((req, res, next) => {
  // Simple validation for query parameters
  if (req.query) {
    Object.entries(req.query).forEach(([key, value]) => {
      if (typeof value === 'string' && value.length > 1000) {
        return res.status(400).json({
          error: 'Input too long',
