// Enhanced app.js with security-focused error handling and input validation
const express = require('express');
const app = express();

// Basic security middleware - no external dependencies needed
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Simple input validation middleware
const validateQueryParams = (req, res, next) => {
  const { limit, offset } = req.query;

  // Validate numeric parameters
  if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
    return res.status(400).json({
      error: 'Invalid parameter',
      message: 'Limit must be an integer between 1 and 100'
    });
  }

  if (offset && (!Number.isInteger(Number(offset)) || Number(offset) < 0)) {
    return res.status(400).json({
      error: 'Invalid parameter',
      message: 'Offset must be a non-negative integer'
    });
  }

  next();
};

// Health endpoint with basic error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', validateQueryParams, (req, res) => {
  try {
    const { limit = 10, offset = 0 } = req.query;

    // Mock data - in real app, validate and sanitize any database inputs
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply basic pagination (safe due to validation)
    const safeLimit = Math.min(Math.max(1, parseInt(limit)), 100);
    const safeOffset = Math.max(0, parseInt(offset));
    const paginatedUsers = users.slice(safeOffset, safeOffset + safeLimit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit: safeLimit,
        offset: safeOffset,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve users'
    });
  }
});

// 404 handler for unknown routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handler (for uncaught exceptions)
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you might want to gracefully shutdown
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

