// Secure application with enhanced error handling and input validation
// This version includes security best practices and proper error handling

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const expressSanitizer = require('express-sanitizer');

const app = express();

// Security middleware setup
app.use(helmet());

// Configure CORS properly
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Request parsing middleware with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(expressSanitizer()); // Must come after body-parser middleware

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method
  });

  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      error: 'Invalid JSON payload',
      message: 'The request contains malformed JSON'
    });
  }

  // Don't expose internal error details in production
  const errorResponse = process.env.NODE_ENV === 'development' 
    ? { error: err.message, stack: err.stack }
    : { error: 'Internal server error' };

  res.status(err.status || 500).json(errorResponse);
});

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  const { page, limit, sort } = req.query;

  // Validate pagination parameters
  if (page && (!Number.isInteger(Number(page)) || Number(page) < 1)) {
    return res.status(400).json({
      error: 'Invalid page parameter',
      message: 'Page must be a positive integer'
    });
  }

  if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
    return res.status(400).json({
      error: 'Invalid limit parameter',
      message: 'Limit must be a positive integer between 1 and 100'
    });
  }

  // Validate sort parameter
  if (sort && !/^[a-zA-Z_,\s]+$/.test(sort)) {
    return res.status(400).json({
      error: 'Invalid sort parameter',
      message: 'Sort parameter contains invalid characters'
    });
  }

  next();
};

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    // Basic input validation for query parameters
    if (Object.keys(req.query).length > 0) {
      return res.status(400).json({
        error: 'No query parameters allowed',
        message: 'Health endpoint does not accept query parameters'
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error during health check'
    });
  }
});

// Users endpoint with validation and filtering
app.get('/users', validateQueryParams, (req, res) => {
  try {
    const { page = 1, limit = 10, sort = 'id' } = req.query;
    const pageNum = parseInt(page);
    const limitNum = parseInt(limit);

    // Sample user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Admin', email: 'admin@example.com', role: 'admin' }
    ];

    // Filter sensitive data - don't expose internal fields
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
      // role is intentionally excluded from response
    }));

    // Simple pagination simulation
    const startIndex = (pageNum - 1) * limitNum;
    const paginatedUsers = sanitizedUsers.slice(startIndex, startIndex + limitNum);

    res.json({
      data: paginatedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: users.length,
        totalPages: Math.ceil(users.length / limitNum)
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

// Error handling for server startup
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
}).on('error', (err) => {
  console.error('Server startup error:', err);
  process.exit(1);
});

module.exports = app;

